# Viva — slot D3 (part B): nutritional & metabolic (4 cases)
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — nutritional chapter (vitamin
# deficiencies, zinc, pellagra causes, hypervitaminosis A, kwashiorkor, nutritional dermatoses), metabolic chapter
# (hyperlipoproteinaemia classification, Tangier's), amyloid stains; facts checked with IADVL 5e.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Pellagra", src=f"{PYQ}; {IA} (Nutritional dermatoses)",
 qa=[
 ("What is pellagra?", ["Systemic disease due to deficiency of niacin (vitamin B3 — nicotinic acid/nicotinamide) or its precursor tryptophan, with photosensitive dermatitis, diarrhoea, dementia and death if untreated — the '4 Ds'", "'Pelle agra' = rough skin (Italian)"]),
 ("Discuss the causes of pellagra (PYQ).", ["Dietary: maize/jowar (sorghum)-based diets — niacin in maize is bound (niacytin) and maize has little tryptophan; sorghum has excess leucine which inhibits tryptophan–niacin conversion; poverty, famine, food faddism", "Alcoholism (commonest in India today), malabsorption (Crohn's, chronic diarrhoea, gastrectomy), anorexia nervosa, HIV, haemodialysis", "Drugs: isoniazid (competes with pyridoxine — needed for conversion), 6-mercaptopurine/azathioprine, 5-fluorouracil, pyrazinamide, ethionamide, phenytoin, phenobarbitone, chloramphenicol", "Carcinoid syndrome (tryptophan diverted to serotonin), Hartnup disease (defective neutral amino-acid transport — SLC6A19), deficiency of riboflavin/pyridoxine (cofactors)"]),
 ("Describe the cutaneous features.", ["Symmetric, sharply demarcated photosensitive dermatitis on sun-exposed sites — dorsa of hands/forearms (gauntlet or glove), feet (boot), face (butterfly-like), neck (Casal's necklace — band around neck in C3/C4 dermatome), V of chest", "Acute: erythema, burning, blistering like sunburn; chronic: dry rough scaly hyperpigmented (dark-brown/'varnished') thickened skin with fissures; sharp upper border", "Perineal/genital involvement (friction), angular cheilitis, glossitis (red smooth swollen 'beefy' tongue), stomatitis, vulvitis/vaginitis"]),
 ("Systemic features.", ["GI: diarrhoea, abdominal pain, nausea, anorexia (atrophy of mucosa)", "Neuropsychiatric: insomnia, irritability, depression, apathy, confusion, memory loss, psychosis, dementia, peripheral neuropathy; encephalopathy in alcoholics", "Weakness, weight loss; death if untreated"]),
 ("How do you diagnose pellagra?", ["Clinical diagnosis with rapid response to niacin (therapeutic test)", "Supportive: low urinary N-methylnicotinamide and 2-pyridone (<1.5 mg/24 h), low serum tryptophan/niacin; check other deficiencies (B1, B2, B6, B12, folate, zinc), LFT (alcohol), 5-HIAA for carcinoid", "Histology non-specific: pallor of upper epidermis, hyperkeratosis, parakeratosis, psoriasiform hyperplasia (similar to necrolytic migratory erythema, acrodermatitis enteropathica — 'deficiency dermatitis')"]),
 ("Differential diagnosis.", ["Photosensitive drug eruption, polymorphic light eruption, chronic actinic dermatitis, airborne contact dermatitis, porphyria cutanea tarda, lupus (SCLE/DM), Hartnup disease, kwashiorkor, necrolytic migratory erythema, Bloom/Cockayne syndromes (children), carcinoid flushing"]),
 ("Treatment.", ["Nicotinamide 100 mg every 6 h (or 300 mg/day) for 3–4 weeks then maintenance (nicotinamide preferred — no flushing); high-protein balanced diet; vitamin B-complex supplements (B1, B2, B6 deficits coexist), zinc", "Photoprotection, emollients for skin; stop alcohol/offending drug; treat carcinoid/malabsorption", "Response: mental symptoms improve within 24–48 h, skin in 1–2 weeks"]),
 ("Discuss cutaneous manifestations of vitamin deficiencies (PYQ).", ["Vitamin A: xerosis, phrynoderma, night blindness, Bitot's spots, keratomalacia", "B2 (riboflavin): angular cheilitis, magenta tongue, seborrhoeic-like dermatitis, oral-ocular-genital syndrome", "B3 (niacin): pellagra", "B6: seborrhoeic dermatitis-like, cheilitis, glossitis, neuropathy", "B12/folate: hyperpigmentation (knuckles, palms), glossitis, angular cheilitis, canities", "Biotin: periorificial dermatitis, alopecia (raw egg-white avidin)", "Vitamin C (scurvy): perifollicular haemorrhage, corkscrew hairs, gingival bleeding, poor healing, woody oedema", "Vitamin K: purpura, ecchymoses", "Zinc: acrodermatitis enteropathica-like; essential fatty acids: xerosis, alopecia"]),
 ("Discuss the role of zinc in dermatology (PYQ).", ["Cofactor for >300 enzymes (metalloproteinases, DNA/RNA polymerase, superoxide dismutase); needed for wound healing, immunity, keratinisation", "Deficiency: acrodermatitis enteropathica (inherited SLC39A4/ZIP4 defect; acquired — prematurity, low breast-milk zinc, TPN, malabsorption, alcoholism, nephrotic syndrome): periorificial and acral eroded psoriasiform dermatitis, alopecia, diarrhoea, paronychia, irritability, infections", "Therapeutic uses: acrodermatitis enteropathica (1–3 mg/kg/day elemental zinc), acne, warts, rosacea, leg ulcers, leishmaniasis, hidradenitis, erosive pustular dermatosis, as adjuvant in leprosy reactions"]),
 ],
 spot=["Photosensitive dermatitis + Casal's necklace + diarrhoea + dementia — pellagra", "Maize diet, alcohol, isoniazid, carcinoid, Hartnup", "Nicotinamide — mind improves first"]),

dict(case="Macular and lichen amyloidosis", src=f"{PYQ}; {IA} (Cutaneous amyloidosis)",
 qa=[
 ("What is amyloidosis? Classify cutaneous amyloidosis.", ["Extracellular deposition of insoluble fibrillar proteins with β-pleated sheet structure that show apple-green birefringence with Congo red", "Primary localised cutaneous amyloidosis (PLCA): keratinocyte-derived (amyloid K) — macular, lichen (papular), biphasic (both), nodular (AL — plasma-cell light chains; risk of systemic progression ~7%), poikiloderma-like, bullous, anosacral, familial (OSMR, IL31RA mutations)", "Secondary localised: in tumours (BCC, seborrhoeic keratosis), PUVA, after injections (insulin amyloid)", "Systemic amyloidosis with skin involvement: AL (primary/myeloma — periorbital 'pinch purpura', waxy papules, macroglossia), AA (secondary — chronic inflammation; skin rarely involved), β2-microglobulin (dialysis), ATTR (familial/senile)"]),
 ("Describe macular amyloidosis.", ["Grey-brown rippled (reticulate) pigmentation on the upper back (interscapular), arms, shins; mild to moderate itch", "Common in Asians, Middle East, Latin Americans; women; friction (nylon scrubs, loofahs, towels — 'friction melanosis' overlap)"]),
 ("Describe lichen amyloidosis.", ["Very itchy, discrete firm hyperkeratotic hyperpigmented papules often in a rippled/linear pattern coalescing into plaques on shins (commonest), extensor forearms, thighs, upper back; men > women", "Associations: atopic dermatitis, MEN 2A (RET), familial (OSMR/IL31RA), chronic friction/scratching, lichen planus, hepatitis/biliary cirrhosis"]),
 ("Pathogenesis.", ["Keratinocyte damage (friction, scratching, UV, genetic) → apoptotic keratinocyte filaments (cytokeratins, especially CK5) altered into amyloid by dermal macrophages/fibroblasts → deposits in papillary dermis", "Itch–scratch cycle perpetuates (IL-31/OSMR pathway)"]),
 ("Describe stains used for amyloid (PYQ).", ["Congo red — salmon pink on light microscopy; apple-green birefringence under polarised light (gold standard)", "Crystal violet / methyl violet — metachromasia (purple-red)", "Thioflavin T / S — yellow-green fluorescence under UV (sensitive)", "Sirius red, PAS (weakly positive, diastase resistant), Alcian blue, Pagoda red, DFF (dylon), cotton dyes (Pagoda red, Dylon) — high sensitivity in skin", "Immunohistochemistry: anti-cytokeratin (34βE12 — PLCA), anti-κ/λ (AL), anti-AA, anti-TTR", "Electron microscopy: non-branching 7.5–10 nm fibrils", "Lugol's iodine (gross specimen — mahogany brown, turning blue with sulphuric acid)"]),
 ("Histopathology of macular/lichen amyloidosis.", ["Small globular eosinophilic deposits in dermal papillae (macular — subtle, needs special stains), with pigment incontinence (melanophages)", "Lichen: larger deposits filling and expanding papillae + hyperkeratosis, acanthosis (features of chronic rubbing)", "Nodular: diffuse deposits throughout dermis, around vessels, with plasma cells (AL type)"]),
 ("Differential diagnosis.", ["Macular: post-inflammatory hyperpigmentation, notalgia paraesthetica (localised itchy patch under scapula — T2–T6 nerve entrapment), friction melanosis, ashy dermatosis, lichen planus pigmentosus, prurigo pigmentosa, confluent and reticulated papillomatosis, tinea versicolor", "Lichen: lichen simplex chronicus, hypertrophic LP, prurigo nodularis, pretibial myxoedema, colloid milium, lichen myxoedematosus"]),
 ("Investigations.", ["Clinical + dermoscopy (central white/brown hub with radiating pigmentation); biopsy with special stains", "If nodular amyloidosis or systemic signs: serum and urine protein electrophoresis, immunofixation, serum free light chains, CBC, renal function, urine protein, echocardiography, abdominal fat-pad aspirate; MEN 2A screening (calcitonin, metanephrines, RET) in familial lichen amyloidosis with family history of medullary thyroid cancer"]),
 ("Management.", ["Avoid friction (no nylon scrubbers), break itch–scratch cycle, sedating antihistamines, emollients, menthol/pramoxine", "Potent topical steroids under occlusion, intralesional triamcinolone (lichen), tacrolimus, calcipotriol, DMSO (dimethyl sulphoxide), capsaicin", "Keratolytics (salicylic acid, urea) for lichen papules; acitretin 0.5 mg/kg/day for extensive lichen amyloidosis", "Phototherapy (NB-UVB, PUVA), cyclosporine, dupilumab/nemolizumab (itch — case reports)", "Procedures: dermabrasion, CO2/Er:YAG laser, Q-switched Nd:YAG (macular pigment), fractional lasers", "Nodular: excision, laser; follow up for systemic AL"]),
 ("Prognosis.", ["Benign chronic course; recurrence common; nodular type needs monitoring for systemic amyloidosis"]),
 ],
 spot=["Rippled grey-brown interscapular pigmentation — macular amyloidosis", "Itchy rippled papules on shins — lichen amyloidosis", "Congo red apple-green birefringence"]),

dict(case="Phrynoderma", src=f"{PYQ}; {IA} (Nutritional dermatoses)",
 qa=[
 ("What is phrynoderma?", ["'Toad skin' — follicular hyperkeratotic papules with a central keratotic plug, classically linked to vitamin A deficiency but now considered a marker of multiple nutritional deficiencies (vitamin A, B-complex, E, essential fatty acids, protein-energy malnutrition)"]),
 ("Clinical features.", ["Dry rough skin with symmetric, firm, skin-coloured to brown follicular papules (2–6 mm) with central horny spines; first on extensor elbows, knees, then thighs, buttocks, shoulders, extensor forearms, back", "School-age children commonest, especially in low-income settings; may coexist with xerophthalmia (night blindness, Bitot's spots, xerosis conjunctivae, keratomalacia), angular cheilitis, glossitis"]),
 ("Discuss features of vitamin A deficiency and hypervitaminosis A (PYQ).", ["Deficiency: xerosis, phrynoderma, hair dryness, night blindness (earliest), conjunctival/corneal xerosis, Bitot's spots, keratomalacia, increased infections (measles severity)", "Hypervitaminosis A (acute — polar bear liver, mega-doses; chronic — retinoid excess): headache, raised intracranial pressure (pseudotumour cerebri), vomiting; skin — dryness, peeling, cheilitis, alopecia, pruritus, hyperpigmentation; bone pain, hepatosplenomegaly, hypercalcaemia, teratogenicity"]),
 ("Histopathology.", ["Follicular hyperkeratosis with keratotic plugs distending the follicle, atrophy of sebaceous glands, mild perifollicular infiltrate"]),
 ("Differential diagnosis.", ["Keratosis pilaris (outer arms/thighs, atopic, finer, lifelong), lichen spinulosus (grouped spiny papules in plaques), pityriasis rubra pilaris (knuckle papules, orange keratoderma), Darier's disease (greasy seborrhoeic papules), follicular eczema, lichen nitidus, scurvy (perifollicular haemorrhage + corkscrew hair), frictional lichenoid eruption, follicular mucinosis"]),
 ("Investigations.", ["Serum retinol (<20 µg/dl deficiency), CBC, total protein/albumin, other vitamins/zinc as indicated; eye examination", "Clinical response to supplementation supports diagnosis"]),
 ("Treatment.", ["Vitamin A: WHO therapy for xerophthalmia — 2 lakh IU (200,000 IU) orally on day 1, day 2 and after 2 weeks (1 lakh IU for 6–12 months, 50,000 IU <6 months)", "Balanced diet with green leafy vegetables, yellow/orange fruits, dairy; B-complex, vitamin E, essential fatty acid (safflower oil) supplements; treat underlying malnutrition, malabsorption", "Topical keratolytics: urea 10–20%, salicylic acid, lactic acid; emollients", "National programme: biannual vitamin A prophylaxis for children 9 months–5 years (India)"]),
 ("Discuss skin changes in kwashiorkor (PYQ).", ["Protein deficiency with adequate calories (1–5 y after weaning): 'flaky-paint' / 'crazy-pavement' dermatosis (hyperpigmented patches that peel leaving pink/hypopigmented areas), especially pressure areas, buttocks and legs", "Hair: dry, sparse, easily pluckable, hypopigmented (reddish-brown), 'flag sign' (alternating bands of light and dark hair indicating periods of poor and good nutrition)", "Oedema (pitting), moon face, hepatomegaly (fatty liver), apathy, growth failure; marasmus: wasting, loose wrinkled skin, 'monkey facies', no oedema"]),
 ],
 spot=["Toad-like follicular spiny papules on elbows/knees of a malnourished child — phrynoderma", "Flag sign — kwashiorkor hair"]),

dict(case="Xanthomas", src=f"{PYQ}; {IA} (Xanthomas and lipid disorders)",
 qa=[
 ("What are xanthomas?", ["Yellowish papules, plaques, nodules or tendon swellings formed by lipid-laden macrophages (foam cells) in skin/tendons — often markers of hyperlipidaemia (primary or secondary) but can occur with normal lipids (normolipaemic)"]),
 ("Describe the clinical types and lipid associations.", ["Eruptive xanthomas: crops of small red-yellow papules with erythematous halo on buttocks, extensors — high triglycerides (types I, IV, V; uncontrolled diabetes) — risk of acute pancreatitis", "Tuberous xanthomas: firm yellow nodules on elbows, knees, buttocks — types II, III (dysbetalipoproteinaemia)", "Tendinous xanthomas: smooth nodules in Achilles tendon, extensor tendons of hands — type IIa familial hypercholesterolaemia (LDL receptor defect), also cerebrotendinous xanthomatosis, sitosterolaemia", "Planar: xanthelasma palpebrarum (eyelids — commonest; ~50% have normal lipids), palmar crease xanthomas (xanthoma striatum palmare — type III dysbetalipoproteinaemia, pathognomonic), intertriginous (finger webs — homozygous FH), diffuse plane xanthomas (normolipaemic — paraproteinaemia/myeloma)", "Verruciform xanthoma (oral/genital), xanthoma disseminatum (non-LCH histiocytosis, normolipaemic, with diabetes insipidus)"]),
 ("Classify primary hyperlipoproteinaemia (Fredrickson — PYQ).", ["Type I: raised chylomicrons (lipoprotein lipase or apo C-II deficiency) — eruptive xanthomas, lipaemia retinalis, pancreatitis, hepatosplenomegaly; childhood", "Type IIa: raised LDL (familial hypercholesterolaemia — LDLR, APOB, PCSK9) — tendon, tuberous xanthomas, xanthelasma, arcus, premature CAD", "Type IIb: raised LDL + VLDL (familial combined) — xanthelasma, tuberous", "Type III: raised IDL/chylomicron remnants (dysbetalipoproteinaemia — apo E2/E2) — palmar crease and tubero-eruptive xanthomas", "Type IV: raised VLDL (familial hypertriglyceridaemia) — eruptive xanthomas; associated diabetes, obesity", "Type V: raised VLDL + chylomicrons — eruptive xanthomas, pancreatitis"]),
 ("Secondary causes of hyperlipidaemia.", ["Diabetes mellitus, hypothyroidism, nephrotic syndrome, chronic kidney disease, cholestasis (primary biliary cholangitis — planar xanthomas), obesity, alcohol, pancreatitis", "Drugs: oral retinoids (isotretinoin, acitretin), oestrogens, corticosteroids, cyclosporine, protease inhibitors, β-blockers, thiazides, olanzapine"]),
 ("Histopathology.", ["Dermal collections of foam cells (macrophages with lipid vacuoles), Touton giant cells (wreath of nuclei), extracellular cholesterol clefts (tuberous/tendinous), inflammation in eruptive xanthomas", "Lipids dissolved during processing — frozen section + Oil Red O / Sudan stains show lipid"]),
 ("Investigations.", ["Fasting lipid profile (total cholesterol, LDL, HDL, triglycerides), lipoprotein electrophoresis, apo E genotype (type III)", "Blood sugar/HbA1c, thyroid function, renal function, urine protein, LFT", "Serum protein electrophoresis/immunofixation for plane xanthomas with normal lipids", "Cardiovascular risk assessment (ECG, lipid targets); family screening for FH"]),
 ("Write short notes on Tangier's disease (PYQ).", ["Autosomal recessive ABCA1 deficiency → almost absent HDL; cholesterol esters accumulate in reticuloendothelial tissues — enlarged orange-yellow tonsils (pathognomonic), hepatosplenomegaly, peripheral neuropathy, premature atherosclerosis, corneal clouding"]),
 ("Treatment of xanthomas.", ["Treat underlying lipid disorder: diet, weight loss, exercise, glycaemic control, treat hypothyroidism; statins, ezetimibe, PCSK9 inhibitors (FH), fibrates/omega-3 for hypertriglyceridaemia — eruptive xanthomas regress in weeks with TG control", "Local for xanthelasma/persistent lesions: TCA 50–70% application, surgical excision, CO2/Er:YAG/Q-switched/fractional lasers, radiofrequency, cryotherapy, intralesional pingyangmycin/bleomycin", "Tendon xanthomas regress slowly with aggressive lipid lowering; surgery only if functional problems"]),
 ("Significance of xanthelasma.", ["Commonest xanthoma; ~50% normolipaemic but independently linked with myocardial infarction and atherosclerosis risk (Copenhagen study) — always check lipids and CV risk"]),
 ],
 spot=["Crops of yellow papules with red halo on buttocks — eruptive xanthomas (high TG → pancreatitis risk)", "Palmar crease xanthomas — type III", "Achilles tendon xanthoma — familial hypercholesterolaemia"]),
]
